import sys
from collections import defaultdict

def parse_grammar(text):
    # split on tokens of form X::=alts
    import re
    parts = re.findall(r'([A-Z])::=([^ \t]+(?:\|[^ \t]+)*)', text)
    rules=[]
    for l,r in parts:
        rules.append((l, r.split('|')))
    return rules

def analyze(text, name):
    rules = parse_grammar(text)
    NT = [l for l,_ in rules]
    start = NT[0]
    prods = []
    for l,alts in rules:
        for a in alts:
            prods.append((l,a))
    T=set()
    for l,a in prods:
        for ch in a:
            if ch not in NT and ch!='@': T.add(ch)
    FIRST=defaultdict(set)
    for t in T: FIRST[t]={t}
    FIRST['@']={'@'}
    changed=True
    while changed:
        changed=False
        for l,a in prods:
            f=first_str(a,FIRST,NT)
            if not f <= FIRST[l]:
                FIRST[l]|=f; changed=True
    FOLLOW=defaultdict(set)
    FOLLOW[start]={'#'}
    changed=True
    while changed:
        changed=False
        for l,a in prods:
            if a=='@': continue
            for i,X in enumerate(a):
                if X in NT:
                    rest=a[i+1:]
                    f=first_str(rest,FIRST,NT) if rest else {'@'}
                    add=(f-{'@'})
                    if '@' in f: add=add|FOLLOW[l]
                    if not add<=FOLLOW[X]:
                        FOLLOW[X]|=add; changed=True
    table={}
    conflicts=[]
    for l,a in prods:
        f=first_str(a,FIRST,NT)
        for t in f-{'@'}:
            if (l,t) in table: conflicts.append((l,t,table[(l,t)],a))
            table[(l,t)]=a
        if '@' in f:
            for t in FOLLOW[l]:
                if (l,t) in table and table[(l,t)]!=a: conflicts.append((l,t,table[(l,t)],a))
                table[(l,t)]=a
    return dict(start=start,NT=NT,T=sorted(T),prods=prods,FIRST=FIRST,FOLLOW=FOLLOW,table=table,conflicts=conflicts)

def first_str(s,FIRST,NT):
    if s=='@' or s=='': return {'@'}
    out=set()
    for ch in s:
        f=FIRST[ch] if (ch in NT or ch in FIRST) else {ch}
        out |= (f-{'@'})
        if '@' not in f: return out
    out.add('@')
    return out

def trace(G, inp):
    NT=G['NT']; table=G['table']
    stack=['#',G['start']]
    rem=list(inp)+['#']
    rows=[]
    step=0
    while True:
        step+=1
        st=''.join(stack); ri=''.join(rem)
        top=stack[-1]; look=rem[0]
        if top=='#' and look=='#':
            rows.append((step,st,ri,'accept')); return rows,True
        if top in NT:
            a=table.get((top,look))
            if a is None:
                rows.append((step,st,ri,'ERROR: M[%s,%s] empty'%(top,look))); return rows,False
            rows.append((step,st,ri,'%s::=%s'%(top,a)))
            stack.pop()
            if a!='@':
                for ch in reversed(a): stack.append(ch)
        else:
            if top==look:
                rows.append((step,st,ri,"match '%s'"%top))
                stack.pop(); rem.pop(0)
            else:
                rows.append((step,st,ri,"ERROR: top '%s' vs input '%s'"%(top,look))); return rows,False
        if step>60:
            rows.append((step,'','','ERROR: loop')); return rows,False

